# -- stubs-r5: the static-initializer stubs (msvc6/static_stub_*.cpp, generated
# by tools/static_inits.py gen with the tables above). The stubs only call
# other functions, so those calls are probed and compared (the callee
# addresses are the stub's operands): entries call their init and jump to
# their registration, registrations call atexit 0x61e812 with the
# destructor stub, destructor stubs jump to the destructor with ECX = the
# global, string inits call std::string(const char*, n) 0x401a10 with the
# literal and npos. The float ratio inits run as they are, on random
# source values (the sources are .rdata constants; a fifth of the cases
# keeps the image's values); the concat inits like wip/logic-r4's above.
def static_stub_guard(guard):
    def generate(rng, pool, args):
        return [(guard, rng.choice([0, 1, rng.randrange(256)]), 1)]
    return generate


def static_stub_ratio_sources(loads):
    byte_addresses = sorted({address + k for address, size in loads for k in range(size)})

    def generate(rng, pool, args):
        if rng.random() < 0.2:
            return []
        values = {a: rng.choice([0, 0xff, rng.randrange(256), rng.randrange(256)]) for a in byte_addresses}
        if rng.random() < 0.15:  # b1 == b0: a zero denominator (infinity or NaN)
            (b1, size1), (b0, size0) = loads[2], loads[3]
            for k in range(min(size1, size0)):
                values[b1 + k] = values.get(b0 + k, 0)
        return [(a, v, 1) for a, v in values.items()]
    return generate


